aws_iam_role.mansion_spirit:
resource "aws_iam_role" "mansion_spirit" {
  name = "mansion-spirit"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "ec2.amazonaws.com" }
      }
    ]
  })
}

aws_iam_role_policy.mansion_spirit_acces:
resource "aws_iam_role_policy" "mansion_spirit_access" {
  name = "mansion-spirit-access"
  role = aws_iam_role.mansion_spirit.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:*"
        Resource = "*"
      }
    ]
  })
}

aws_instance.mansion:
resource "aws_instance" "mansion" {
  ami                         = "ami-0123456789abcdef0"
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.graveyard.id
  vpc_security_group_ids      = [aws_security_group.mansion_gate.id]
  iam_instance_profile        = aws_iam_instance_profile.mansion.name
  associate_public_ip_address = true

  tags = {
    Name = "haunted-mansion"
  }
}

aws_vpc.kingdom:
resource "aws_vpc" "kingdom" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "haunted-kingdom"
  }
}

aws_subnet.graveyard:
resource "aws_subnet" "graveyard" {
  vpc_id                  = aws_vpc.kingdom.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "graveyard-public"
  }
}

aws_subnet.crypt_a:
resource "aws_subnet" "crypt_a" {
  vpc_id            = aws_vpc.kingdom.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "crypt-private-a"
  }
}

aws_subnet.crypt_b:
resource "aws_subnet" "crypt_b" {
  vpc_id            = aws_vpc.kingdom.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "crypt-private-b"
  }
}

aws_route.graveyard_internet:
resource "aws_route" "graveyard_internet" {
  route_table_id         = aws_route_table.graveyard_road.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gate.id
}

aws_security_group.mansion_gate:
resource "aws_security_group" "mansion_gate" {
  name        = "mansion-gate"
  description = "Traffic rules for the mansion web server"
  vpc_id      = aws_vpc.kingdom.id
}

aws_security_group.tomb_ward:
resource "aws_security_group" "tomb_ward" {
  name        = "tomb-ward"
  description = "Traffic rules for the database"
  vpc_id      = aws_vpc.kingdom.id
}
